// Generated by ds-sync (radio template, Web Components) from Figma "RadioGroup". Do not edit by hand.
// Visuals come from Figma. Behaviour: WAI-ARIA radio group pattern (native radio inputs; the group manages selection, arrow keys and the Tab stop across shadow roots).
import { LitElement, html, nothing, unsafeCSS } from 'lit';

import '../RadioField/ds-radio-field';
import css from './RadioGroup.css?inline';

/** What the group needs from a radio control. */
type Radio = HTMLElement & { checked: boolean; value: string; name?: string; disabled: boolean; tabStop: boolean; groupReadOnly: boolean; select(): void };

export class DsRadioGroup extends LitElement {
  static override styles = [unsafeCSS(':host { display: contents; }'), unsafeCSS(css)];
  static override properties = {
    label: { type: String },
    name: { type: String },
    value: { type: String, reflect: true },
    state: { type: String, reflect: true, attribute: "state" },
    horizontal: { type: Boolean, reflect: true, attribute: "horizontal" },
    disabled: { type: Boolean, reflect: true },
    forceState: { type: String, attribute: 'data-force-state' },
  };

  /** Figma: the group label ("Delivery speed") */
  declare label: string | undefined;
  /** Shared name for the radios inside */
  declare name: string | undefined;
  /** Selected value */
  declare value: string | undefined;
  /** Figma: State */
  declare state: "enabled" | "read-only" | "invalid" | "warning";
  /** Figma: Horizontal */
  declare horizontal: boolean;
  /** Disables every radio inside */
  declare disabled: boolean;
  /** Renders a pseudo state statically for docs and visual tests: "hover", "pressed" or "focus". */
  declare forceState: string | undefined;

  /** The radios inside, in registration (document) order. */
  private radios: Radio[] = [];
  private readonly uid = `ds-radio-${Math.random().toString(36).slice(2, 8)}`;

  constructor() {
    super();
    this.label = undefined;
    this.name = undefined;
    this.value = undefined;
    this.state = "enabled";
    this.horizontal = false;
    this.disabled = false;
    this.addEventListener('ds-radio-register', (event) => {
      event.stopPropagation();
      const radio = (event as CustomEvent<Radio>).detail;
      if (!this.radios.includes(radio)) this.radios.push(radio);
      this.configure(radio);
      queueMicrotask(() => this.syncTabStops());
    });
    this.addEventListener('ds-radio-select', (event) => {
      event.stopPropagation();
      const selected = (event as CustomEvent<Radio>).detail;
      for (const radio of this.live()) if (radio !== selected) radio.checked = false;
      if (this.value !== selected.value) {
        this.value = selected.value;
        this.dispatchEvent(new CustomEvent('value-change', { detail: selected.value, bubbles: true, composed: true }));
      }
      this.syncTabStops();
    });
    this.addEventListener('ds-radio-move', (event) => {
      event.stopPropagation();
      const { from, delta } = (event as CustomEvent<{ from: Radio; delta: number }>).detail;
      const enabled = this.live().filter((radio) => !radio.disabled);
      const next = enabled[(enabled.indexOf(from) + delta + enabled.length) % enabled.length];
      if (!next) return;
      next.select();
      next.focus();
    });
  }

  private live() {
    return this.radios.filter((radio) => radio.isConnected);
  }

  private configure(radio: Radio) {
    if (!radio.name) radio.name = this.name ?? this.uid;
    if (this.value !== undefined) radio.checked = radio.value === this.value;
    if (this.disabled) radio.disabled = true;
    radio.groupReadOnly = this.state === 'read-only';
  }

  /** WAI-ARIA radio group: one Tab stop, on the selected radio (or the first enabled one). */
  private syncTabStops() {
    const radios = this.live();
    const stop = radios.find((radio) => radio.checked && !radio.disabled) ?? radios.find((radio) => !radio.disabled);
    for (const radio of radios) radio.tabStop = radio === stop;
  }

  override updated(changed: Map<string, unknown>) {
    if (changed.has('value') || changed.has('disabled') || changed.has('name') || changed.has('state')) {
      for (const radio of this.live()) this.configure(radio);
      this.syncTabStops();
    }
  }

  override render() {
    return html`<div class="root" part="root" role="radiogroup" aria-labelledby="label" aria-invalid=${this.state === 'invalid' ? 'true' : nothing} aria-readonly=${this.state === 'read-only' ? 'true' : nothing} aria-disabled=${this.disabled ? 'true' : nothing} data-state=${this.state} data-horizontal=${this.horizontal ? 'true' : 'false'} ?data-disabled=${this.disabled} data-force-state=${this.forceState ?? nothing}>
        <span class="groupLabel" id="label">${this.label ?? "Delivery speed"}</span>
        <div class="items"><slot>
          <span class="radioField"><ds-radio-field></ds-radio-field></span>
          <span class="radioField"><ds-radio-field></ds-radio-field></span>
          <span class="radioField"><ds-radio-field></ds-radio-field></span>
        </slot></div>
        <div class="groupStatus">
          <span class="pleaseSelectADeliveryOption">${"Please select a delivery option"}</span>
          <span class="deliveryEstimateMayVaryByRegion">${"Delivery estimate may vary by region"}</span>
        </div>
      </div>`;
  }
}

if (!customElements.get('ds-radio-group')) customElements.define('ds-radio-group', DsRadioGroup);

declare global {
  interface HTMLElementTagNameMap {
    'ds-radio-group': DsRadioGroup;
  }
}
